<?php
$records = $supervisorWorkflow['records'] ?? [];
$placements = $supervisorWorkflow['placements'] ?? [];
$success = take_flash('success');
$error = take_flash('error');
?>
<div class="dashboard-stack">
<?php if (is_string($success)&&$success!== ''): ?><div class="alert alert-success"><?= app_escape($success) ?></div><?php endif; ?>
<?php if (is_string($error)&&$error!== ''): ?><div class="alert alert-danger"><?= app_escape($error) ?></div><?php endif; ?>
<section class="panel-card"><div class="panel-card-header"><div><h2 class="h5 mb-1">Attendance verification</h2><p class="text-muted mb-0">Only placements from companies linked to this supervisor are shown.</p></div></div>
<?php if ($records !== []): ?><div class="table-responsive"><table class="table data-table attendance-verification-table align-middle"><thead><tr><th>Student</th><th>Company / Position</th><th>Date</th><th>Hours</th><th>Status</th><th>Review</th></tr></thead><tbody>
<?php foreach ($records as $record): ?><tr><td><strong><?= app_escape($record['student_name']) ?></strong><div class="small text-muted"><?= app_escape($record['student_number']) ?></div></td><td><?= app_escape($record['company_name'].' / '.$record['position_title']) ?></td><td><?php $attendanceDate = date_create((string) $record['attendance_date']); echo app_escape($attendanceDate ? date_format($attendanceDate, 'M d, Y') : $record['attendance_date']); ?></td><td><?= app_escape($record['total_hours']) ?></td><td><?php app_render_component('status-badge',['status'=>$record['status']]); ?></td><td><?php if ($record['status']==='pending'): ?><form class="attendance-review-form" method="post" action="<?= app_escape(app_route_url('supervisor/workflow',$appBase)) ?>"><input type="hidden" name="action" value="attendance_review"><input type="hidden" name="csrf_token" value="<?= app_escape(csrf_token()) ?>"><input type="hidden" name="attendance_id" value="<?= (int)$record['id'] ?>"><select class="form-select form-select-sm" name="review_status" aria-label="Attendance decision"><option value="verified">Verify</option><option value="rejected">Reject</option></select><input class="form-control form-control-sm" name="remarks" maxlength="255" placeholder="Remarks"><button class="btn btn-sm btn-primary" type="submit">Save</button></form><?php else: ?><?= app_escape($record['remarks'] ?: '—') ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><?php app_render_component('empty-state',['title'=>'No attendance records','message'=>'Linked company attendance submissions will appear here.']); ?><?php endif; ?></section>

<section class="panel-card"><div class="panel-card-header"><div><h2 class="h5 mb-1">Placement evaluations</h2><p class="text-muted mb-0">Submit a 1–5 rating for trainees in linked companies.</p></div></div>
<?php if ($placements !== []): ?><div class="table-responsive"><table class="table data-table align-middle"><thead><tr><th>Student</th><th>Placement</th><th>Status</th><th>Evaluation</th></tr></thead><tbody><?php foreach ($placements as $placement): ?><tr><td><?= app_escape($placement['student_name']) ?></td><td><?= app_escape($placement['company_name'].' / '.$placement['position_title']) ?></td><td><?php app_render_component('status-badge',['status'=>$placement['status']]); ?></td><td><?php if ($placement['status'] !== 'completed' && $placement['status'] !== 'active'): ?><?= app_escape('Activate or complete first') ?><?php else: ?><form method="post" action="<?= app_escape(app_route_url('supervisor/workflow',$appBase)) ?>"><input type="hidden" name="action" value="evaluation_submit"><input type="hidden" name="csrf_token" value="<?= app_escape(csrf_token()) ?>"><input type="hidden" name="placement_id" value="<?= (int)$placement['id'] ?>"><div class="d-flex gap-1"><select class="form-select form-select-sm" name="rating"><option value="1"<?= (int)$placement['rating']===1?' selected':'' ?>>1</option><option value="2"<?= (int)$placement['rating']===2?' selected':'' ?>>2</option><option value="3"<?= (int)$placement['rating']===3?' selected':'' ?>>3</option><option value="4"<?= (int)$placement['rating']===4?' selected':'' ?>>4</option><option value="5"<?= (int)$placement['rating']===5?' selected':'' ?>>5</option></select><input class="form-control form-control-sm" type="date" name="evaluation_date" value="<?= app_escape($placement['evaluation_date'] ?: date('Y-m-d')) ?>"><input class="form-control form-control-sm" name="comments" maxlength="5000" value="<?= app_escape($placement['comments'] ?: '') ?>" placeholder="Comments"><button class="btn btn-sm btn-primary" type="submit">Save</button></div></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div>
